mapper.sql:
WHERE p.id=#{q.productId} AND p.deleted=0 AND pc.deleted=0
AND pc.id=#{q.colorId}AND l.channel_id=#{q.channelId}
AND s.size=#{q.variantSize}AND l.on_sale=#{q.onSale}

mapper.update:
UPDATE listing l JOIN sku s ON s.id=l.sku_id JOIN product_color pc ON pc.id=s.color_id JOIN product p ON p.id=pc.product_id
l.price=#{price},l.on_sale=#{onSale},
WHERE pc.deleted=0 AND p.deleted=0 AND l.id IN #{id}
